### Version

1.44.1

### Steps to reproduce

###Create a local Dev Server (this one is in node):
```
const http = require("http");

function onRequest (request, response){
    const urlObject = new URL(request.url, 'https://example.com');
    const next_url = urlObject.searchParams.get('next_url');
    const pathname = urlObject.pathname;

    switch (pathname){
        case "/redirect":
            response.writeHead(302, {'Location': next_url});
            response.end();
            break;
    }
}

http.createServer(onRequest).listen(8080);
```
- Run by `node server.js`

###Create a test which sets headers in context.route:
```
// @ts-check
const { test, expect } = require('@playwright/test');

test('redirect with custom headers', async ({ page, context }) => {
  await context.route('**/*', async (route, request) => {
    const headers = request.headers();
    const url = request.url();

    headers['x-custom-header'] = 'value';

    await route.fallback({ headers });
  });

  // redirects the page with 302 to next_url
  await page.goto('http://localhost:8080/redirect?next_url=https://manytools.org/http-html-text/http-request-headers');

  await expect(1).toBe(2); // Only to fail & see the trace
});
```
Playwright Config
